const config = { retries: null, tags: ["a"] };

function read(key, fallback) {
  if (config[key] === undefined) {
    return fallback;
  }

  return config[key];
}

console.log(read("retries", 3));
console.log(read("timeout", 30));
console.log(read("timeout"));
console.log(typeof read("retries"));
console.log(config.tags[1] === config.missing);
